  'Bu Google hesabı zaten başka bir kayıtta bağlı görünüyor. {provider} mülk seçicisini açıp hesabın yanındaki "Hesabı kaldır"a basın, sonra yeniden bağlayın.':
    'Questo account Google appare già collegato a un altro record. Apri il selettore di proprietà del {provider}, fai clic su "Rimuovi account" accanto all\'account, quindi collegalo di nuovo.',
  "Bu Google hesabı zaten başka bir kayıtta bağlı görünüyor. Ayarlar'daki mülk seçicisinden hesabı kaldırıp yeniden bağlayın.":
    "Questo account Google appare già collegato a un altro record. Rimuovi l'account dal selettore proprietà in Impostazioni, quindi collegalo di nuovo.",
