  "Üslup, kullanılmayacak kelimeler, girilmeyecek konular.":
    "Tono, parole da evitare, argomenti da non trattare.",
  "örn. Bağımsız restoranlar için rezervasyon yazılımı. Alıcılar pazarlamacı değil, işletme sahipleri.":
    "es. Software di prenotazione per ristoranti indipendenti. I clienti sono i titolari, non i responsabili marketing.",
  "örn. Dördüncü çeyreğe kadar organik üyelikleri ikiye katlamak. Karşılaştırma sayfaları şu anki öncelik.":
    "es. Raddoppiare le iscrizioni organiche entro il quarto trimestre. Le pagine comparative sono la priorità attuale.",
  "örn. Bir öğleden sonrada kurulan tek rezervasyon aracı. Mevcut rakiplerden ucuz, kendin yap çözümlerden basit.":
    "es. L’unico strumento di prenotazione che configuri in un pomeriggio. Più economico dei concorrenti tradizionali e più semplice delle soluzioni fai-da-te.",
  "örn. Sade ve doğrudan, abartı yok. “Kusursuz” ya da “devrim niteliğinde” yazmayın. Rakip fiyatlarına girmeyin.":
    "es. Semplice e diretto, senza esagerazioni. Non usare “impeccabile” o “rivoluzionario”. Non parlare dei prezzi dei concorrenti.",
