  "Hazırlanan raporlar. Her raporu açabilir, indirebilir ya da silebilirsiniz.":
    "Report preparati. Puoi aprire, scaricare o eliminare ciascun report.",
  Şablonlar: "Modelli",
  "Raporlar yüklenemedi": "Impossibile caricare i report",
  "Şablon silindi": "Modello eliminato",
  "Şablon silinemedi": "Impossibile eliminare il modello",
  "Rapor şablonları": "Modelli di report",
  "Şablon, ajanınıza raporu nasıl yazacağını söyler. Kim okuyacak, hangi bölümler olacak, hangi dilde yazılacak, hepsi burada durur. Ajan rapor yazarken uygun olanı seçer.":
    "Un modello indica all’agente come scrivere un report: chi lo leggerà, quali sezioni includere e in quale lingua. Quando scrive un report, l’agente sceglie il modello più adatto.",
  "Şablonlar yüklenemedi": "Impossibile caricare i modelli",
  "Bu şablondan üretilmiş raporlar etkilenmez.":
    "I report creati con questo modello non saranno modificati.",
  "Şablonu sil": "Elimina modello",
  "Bu rapor yok ya da erişiminiz bulunmuyor.":
    "Questo report non esiste oppure non hai accesso.",
  "Bu raporu okumak için oturum açın.": "Accedi per leggere questo report.",
  "Bu proje arşivde, bu yüzden raporları gizli. Okumak için {name} projesini geri alın.":
    "Questo progetto è archiviato, quindi i suoi report sono nascosti. Ripristina il progetto {name} per leggerli.",
  "Kayıtlı kelimeler yüklenemedi":
    "Impossibile caricare le parole chiave salvate",
  "{count} kelime kopyalandı": {
    one: "Copiata {count} parola chiave",
    other: "Copiate {count} parole chiave",
  },
  "Önce Ayarlar'da Google erişim anahtarını ya da hizmet hesabını girin. Sonra izleyeceğiniz siteyi seçin. Google buna mülk der. Siteyi yeni doğruladıysanız Google'ın veri vermesi birkaç gün sürebilir.":
    "Inserisci prima la chiave di accesso Google o l’account di servizio in Impostazioni. Poi seleziona il sito da monitorare: Google lo chiama proprietà. Se lo hai verificato da poco, Google potrebbe impiegare alcuni giorni per fornire i dati.",
  "Search Console'daki Google erişim anahtarını kullanır, ayrı kurulum istemez. Bağlandıktan sonra Analytics'teki sitenizi (Analytics mülkü) seçin. Organik ziyaretler Panel'de ve Analytics ekranında görünür.":
    "Usa la stessa chiave di accesso Google di Search Console, senza una configurazione separata. Dopo la connessione, seleziona il sito in Analytics (la proprietà Analytics). Le visite organiche appariranno nel Pannello e nella schermata Analytics.",
  Genel: "Generale",
  "Ayar bölümleri": "Sezioni delle impostazioni",
  "Projeler yüklenemedi": "Impossibile caricare i progetti",
  Bitti: "Fine",
  Başarısız: "Non riuscito",
  "Sitenizde düzeltmeniz gereken her şey, önem sırasına göre. Bir satıra tıklayın. Neden önemli olduğunu, nasıl düzelteceğinizi ve hangi sayfaların etkilendiğini adresleriyle görürsünüz.":
    "Tutto ciò che sul tuo sito deve essere corretto, la cosa più importante per prima. Fai clic su una riga per vedere perché è importante, come risolverlo e quali pagine sono interessate, con i relativi indirizzi.",
  "Taranan her sayfa ve sunucunun ona verdiği yanıt. Hatalı, yavaş ya da derinde kalmış sayfaları buradan bulun.":
    "Ogni pagina scansionata e il modo in cui il server ha risposto. Trova pagine danneggiate, lente o profondamente sepolte qui.",
  "Google bu sayfaları gerçekten dizinine almış mı? Almadıysa nedenini burada görürsünüz.":
    "Google ha effettivamente indicizzato queste pagine? In caso contrario, puoi scoprirne il motivo qui.",
  "Sayfalarınız telefonda ve bilgisayarda ne kadar hızlı açılıyor? Ölçüm, Google'ın kullandığı Lighthouse ile yapılır.":
    "Quanto velocemente vengono caricate le tue pagine su telefoni e computer? Misurato con Lighthouse, lo strumento utilizzato da Google.",
