  "Kota doldu": "Quota utilizzata up",
  "{marker}; {measured} sayfa ölçüldü, {left} sayfa ölçülemedi. Google'ın ücretsiz günlük ölçüm sınırı bitti, sayfalarınızda bir sorun yok. Ayarlar'dan bir PageSpeed anahtarı ekleyin ya da kota yenilenince denetimi yeniden başlatın.":
    "{marker}: pagine misurate {measured}, non misurate {left}. Il limite di misurazione giornaliera gratuita di Google è scaduto; non c'è niente che non va nelle tue pagine. Aggiungi una chiave PageSpeed ​​in Impostazioni o esegui nuovamente il controllo una volta reimpostata la quota.",
  "PageSpeed anahtarı girilmediği için {count} ölçüm yapılamadı: Google'ın ortak ücretsiz kotası doldu, sayfalarınızda bir sorun yok. Ayarlar'dan ücretsiz bir anahtar ekleyip denetimi yeniden başlatın.":
    {
      one: "La misurazione di {count} non può essere eseguita perché non è impostata alcuna chiave PageSpeed: la quota gratuita condivisa di Google è esaurita; non c'è niente che non va nelle tue pagine. Aggiungi una chiave gratuita in Impostazioni ed esegui nuovamente il controllo.",
      other:
        "{count} misurazioni non possono essere eseguite perché non è impostata alcuna chiave PageSpeed: la quota gratuita condivisa di Google è esaurita; non c'è niente che non va nelle tue pagine. Aggiungi una chiave gratuita in Impostazioni ed esegui nuovamente il controllo.",
    },
  "Google'ın dakikalık sınırı yüzünden {count} ölçüm yapılamadı; denetimi daha sonra yeniden başlatın veya Ayarlar'dan anahtarınızın kotasını kontrol edin.":
    {
      one: "Impossibile eseguire la misurazione di {count} a causa del limite al minuto di Google. Esegui di nuovo il controllo più tardi o controlla la quota della tua chiave nelle Impostazioni.",
      other:
        "{count} misurazioni non possono essere eseguite a causa del limite al minuto di Google. Esegui di nuovo il controllo più tardi o controlla la quota della tua chiave in Impostazioni.",
    },
