  "{count} sayfada engellendik.": {
    one: "Siamo stati bloccati su {count} pagina.",
    other: "Siamo stati bloccati su {count} pagine.",
  },
  "Sitenin bot koruması tarayıcımızı durdurdu, o sayfalar denetlenemedi. Henüz bir çözümümüz yok. Masaüstü tarayıcılar sizin bilgisayarınızdan çalıştığı için genelde geçer. Şunları deneyin: {librecrawl} (ücretsiz, açık kaynak) ya da {screamingfrog} (500 adrese kadar ücretsiz).":
    "La protezione dai bot del sito ha bloccato il nostro crawler, quindi non è stato possibile controllare quelle pagine. Non abbiamo ancora una soluzione alternativa. I crawler desktop di solito riescono a passare perché vengono eseguiti dal tuo computer. Prova {librecrawl} (gratuito, open source) o {screamingfrog} (fino a 500 URL gratuiti).",
  "Tarama, sitenin istek sınırı yüzünden erken durdu.":
    "La scansione si è interrotta presto a causa del limite di velocità del sito.",
  "Site {count} sayfada istek sınırı uyguladı.": {
    one: "La pagina {count} del sito con tariffa limitata.",
    other: "Il {count} del sito con tariffa limitata pagine.",
  },
  "İstenen bekleme süresi denetim süresini aştı, bazı adresler ziyaret edilmedi. Bu rapor eksik.":
    "L'attesa richiesta dal sito ha superato il limite di tempo del controllo, pertanto alcuni URL non sono stati visitati. Questo rapporto è incompleto.",
  'Sunucunun "çok fazla istek" (429) yanıtı verdiği sayfalar denetlenemedi.':
    'Le pagine in cui il server ha risposto a "troppe richieste" (429) non possono essere controllate.',
  'İstek sınırı sıfırlandıktan sonra denetimi yeniden başlatın, ya da site sahibinden "seotracker-audit" tarayıcısına izin vermesini isteyin.':
    'Esegui di nuovo il controllo una volta reimpostato il limite di velocità o chiedi al proprietario del sito di consentire il crawler "seotracker-audit".',
