  "Hangi kelimelerle arandığınız henüz görünmüyor":
    "Le parole chiave con cui le persone ti cercano non sono ancora visibili",
  "Sitenizin hangi aramalarda kaçıncı sırada çıktığını burada izlersiniz. Search Console kelime bazında veri verdikçe birikir. Az ziyaretçisi olan sitelerde birkaç hafta sürebilir. O zamana kadar toplam tıklama ve gösterime Arama performansı'ndan bakın.":
    "Qui puoi monitorare la posizione in cui viene visualizzato il tuo sito per ogni ricerca. Si accumula man mano che Search Console condivide i dati a livello di parola chiave, il che può richiedere alcune settimane su siti a basso traffico. Fino ad allora, controlla i clic e le impressioni totali nel rendimento della Ricerca.",
