    "Tutte le pagine dei candidati ({candidates})",
  "{analytics}'te karşılığı var": "Trovato in {analytics}",
  "{candidates} aday içinde": "Di {candidates} candidati",
  "{analytics}'te karşılığı yok": "Non trovato in {analytics}",
  "Listedeki her sayfanın Analytics karşılığı var":
    "Ogni pagina elencata ha una corrispondenza in Analisi",
  "Listelenen {rows} sayfanın {count} tanesi · listele":
    "{rows} di {count} pagine elencate · mostrale",
  "En yüksek puan": "Punteggio massimo",
  "{page} · ayrıntı": "{page} · dettagli",
  "Puan nasıl hesaplanır?": "Come viene calcolato il punteggio?",
  "Talep (%50) + iş değeri (%30) + yükselme kolaylığı (%20). İş değeri dönüşüm tanımlı olmadığı için etkileşim oranına göre hesaplanır.":
    "Domanda (50%) + valore aziendale (30%) + facilità di ascesa (20%). Il valore aziendale si basa sul tasso di coinvolgimento, poiché non vengono impostati eventi chiave.",
  "Talep (%50) + iş değeri (%30) + yükselme kolaylığı (%20). İş değeri etkileşim oranına göre hesaplanır.":
    "Domanda (50%) + valore aziendale (30%) + facilità di ascesa (20%). Il valore aziendale si basa sul tasso di coinvolgimento.",
  "Talep (%50) + iş değeri (%30) + yükselme kolaylığı (%20). İş değeri dönüşümlere göre hesaplanır.":
    "Domanda (50%) + valore aziendale (30%) + facilità di ascesa (20%). Il valore aziendale si basa su eventi chiave.",
  "Analytics'te karşılığı yok ne demek?":
    'Cosa significa "non trovato in Analytics"?',
  "Analytics o sayfaya hiç ziyaret görmemiş ya da adresi farklı yazılmış olabilir. Bu sayfalar da puanlanır. İş değerinde haksız yere sıfır almasınlar diye ortada bir değer verilir.":
    "Analytics potrebbe non aver rilevato visite a quella pagina o registrato il suo indirizzo in modo diverso. Anche queste pagine hanno un punteggio; ottengono un valore aziendale medio in modo da non ottenere ingiustamente un punteggio pari a zero.",
  "Bu seçenek yalnızca Windows paketinde kullanılabilir.":
    "Questa opzione è disponibile solo nell'app Windows.",
  "Windows ayarı kaydedilemedi. Tepsi uygulamasının açık olduğunu ve ayarın yönetici tarafından kilitlenmediğini kontrol edip tekrar deneyin.":
    "Non è stato possibile salvare la preferenza di Windows. Verifica che l'app nella barra delle applicazioni sia in esecuzione e che la preferenza non sia bloccata da un amministratore, quindi riprova.",
  "Giriş yok: uygulama yalnızca bu bilgisayarda kullanılır. İnternete açacaksanız önüne kendi girişinizi koyun.":
    "Nessun accesso: l'app è pensata per essere utilizzata solo su questo computer. Se lo esponi a Internet, metti davanti ad esso il tuo accesso.",
  "Cloudflare Access belirteci reddedildi: hedef kitle uyuşmuyor. POLICY_AUD, Access uygulamanızın AUD etiketiyle aynı değil — Zero Trust -> Access controls -> Applications -> Configure -> Additional settings yolundan kopyalayın.":
    "Token di accesso Cloudflare rifiutato: mancata corrispondenza del pubblico. POLICY_AUD non corrisponde al tag AUD della tua applicazione di accesso: copialo da Zero Trust -> Controlli di accesso -> Applicazioni -> Configura -> Impostazioni aggiuntive.",
  "Cloudflare Access belirteci reddedildi: veren taraf uyuşmuyor. TEAM_DOMAIN, belirteci veren Cloudflare ekibiyle aynı değil — Zero Trust ayarlarındaki ekip alan adınızla karşılaştırın.":
    "Token di accesso Cloudflare rifiutato: mancata corrispondenza dell'emittente. TEAM_DOMAIN non corrisponde al team Cloudflare che ha emesso il token: confrontalo con il dominio del team nelle impostazioni Zero Trust.",
  "Cloudflare Access belirteci TEAM_DOMAIN'in imza anahtarlarıyla doğrulanamadı. TEAM_DOMAIN'in ekibinizin https://<team>.cloudflareaccess.com adresi olduğundan emin olun.":
    "Non è stato possibile verificare il token di accesso Cloudflare con le chiavi di firma di TEAM_DOMAIN. Assicurati che TEAM_DOMAIN sia l'indirizzo https://<team>.cloudflareaccess.com del tuo team.",
  "Bu projede böyle bir denetim bulunamadı.":
    "Questo progetto non ha tale controllo.",
  "Denetim ayarları geçersiz.": "Le impostazioni di controllo non sono valide.",
  "Çalışan denetimin durumu doğrulanamadı; silme iptal edildi. Lütfen tekrar deneyin.":
    "Impossibile confermare lo stato del controllo in corso, quindi non è stato eliminato. Riprova.",
  "Çalışan denetim durdurulamadı.":
    "Impossibile interrompere il controllo in esecuzione.",
  "Bu denetim şu an silinemiyor. Bitmesini bekleyip yeniden deneyin.":
    "Questo controllo non può essere eliminato in questo momento. Attendi il completamento e riprova.",
  "Denetimin Lighthouse çıktıları silinemedi; denetim silinmedi. Lütfen tekrar deneyin.":
    "Impossibile eliminare i risultati Lighthouse del controllo, quindi il controllo non è stato eliminato. Riprova.",
