    "Nessuna risposta di Google viene memorizzata per questo controllo, quindi la sezione è vuota.",
  "Listelerdeki kesintiler": "Taglia gli elenchi",
  "Dosya boyutunu makul tutmak için her sorunun altında en fazla {issuePages} adres, sayfa tablosunda {pages} sayfa, hız tablosunda {speed} sayfa yazılır; kesilen her listenin altında kaç kaydın dışarıda kaldığı belirtilir. Tam kayıtlar denetim ekranındadır.":
    "Per mantenere la dimensione del file ragionevole, ogni problema elenca al massimo gli indirizzi {issuePages}, la tabella delle pagine {pages} pagine e la tabella della velocità {speed} pagine; ogni distinta di taglio indica quanti record sono stati omessi. I record completi sono nella schermata di controllo.",
