  "Bu denetimde hız ölçümü kapalıydı, bu yüzden sayfa hızı hakkında bir şey söylenmiyor.":
    "La misurazione della velocità era disattivata per questo audit, quindi non viene detto nulla sulla velocità della pagina.",
  "Bu denetimde kayıtlı Lighthouse sonucu yok: hız ölçümü kapalıydı ya da ölçümler tamamlanamadı (ör. ölçüm servisi istek sınırına takıldı). Hız ölçülmediği için bu rapor hız hakkında bir şey söylemez.":
    "Questo audit non ha risultati Lighthouse memorizzati: la misurazione della velocità era disattivata oppure le misurazioni non potevano terminare (ad esempio, il servizio di misurazione ha raggiunto il limite di richieste). Poiché la velocità non è stata misurata, questo rapporto non dice nulla al riguardo.",
