  "Sürümünüz v{version}.": "Sei attivo v{version}.",
  "Yeni sürüm {version} çıktı": "La versione {version} è uscita",
  "Sürümünüz v{version}. Güncelleme kontrolü başarısız oldu; son bilinen sürüm {latest}.":
    "Sei su v{version}. Il controllo dell'aggiornamento non è riuscito; l'ultima versione conosciuta è {latest}.",
  "Sürümünüz v{version}, güncel.": "Sei su v{version}, l'ultima.",
  "Sürümünüz v{version}. Güncelleme kontrolü kapalı.":
    "Sei su v{version}. I controlli degli aggiornamenti sono disattivati.",
