  "Hızlı işlemler": "Rapida azioni",
  "Durumu yeniden kontrol et": "Controlla di nuovo lo stato",
  "(yeni sekmede açılır)": "(si apre in una nuova scheda)",
  "Becerileri /seo-audit diye çağırırsınız.":
    "Chiami le competenze come /seo-audit.",
  "Komut, Codex'in kendi bağlama adımlarını kullanır. Becerileri $seo-audit diye çağırırsınız.":
    "Il comando utilizza i passaggi di connessione propri del Codex. Le competenze si chiamano $seo-audit.",
  "Genel komut. Beceriyi aracınızın kendi yöntemiyle çağırın.":
    "Un comando generale. Chiama la competenza come fa il tuo strumento.",
  "Uygulama kurulu, Google ve PageSpeed hazırsa yalnızca bu adım yeter.":
    "Se l'app è installata e Google e PageSpeed ​​sono pronti, questo passaggio è tutto ciò che ti serve.",
  "Komutu ajanınıza yapıştırın. Ajan seowatcher'ı bağlar, SEO becerilerini kurar, elle yapacağınız adımlarda size yol gösterir.":
    "Incolla il comando nel tuo agente. Collega seowatcher, installa le competenze SEO e ti guida attraverso i passaggi che esegui manualmente.",
  "Hangi ajanı kullanıyorsunuz?": "Quale agente usi?",
  "Ajan bağlantıyı kurar, becerileri kopyalar ve doğrular. Parolayı sohbete yazmaz, bilgisayarınızdan okur.":
    "L'agente configura la connessione, copia le competenze e le verifica. Legge la password dal tuo computer invece di scriverla nella chat.",
  "Kurulum komutunu kopyala": "Copia comando di configurazione",
  "Kurulum komutu kopyalandı": "Comando di configurazione copiato",
  "Bağlandıktan sonra ajanınızdan {skill} becerisini kullanmasını isteyin; sıradaki adımı birlikte seçersiniz.":
    "Una volta connesso, chiedi al tuo agente di utilizzare la competenza {skill}; sceglierete insieme il passaggio successivo.",
  "Ajanınız seowatcher'a ilk kez istek attığında yukarıdaki durum değişir.":
    "Lo stato sopra cambia la prima volta che il tuo agente invia una richiesta a seowatcher.",
  "Claude Code, Codex, Cursor, ChatGPT ve MCP destekleyen diğer uygulamalarla çalışır.":
    "Funziona con Claude Code, Codex, Cursor, ChatGPT e altre app che supportano MCP.",
  "İlk kez mi kuruyorsunuz? Buradan başlayın.":
    "Stai configurando per la prima volta? Inizia qui.",
  "Sıfırdan kurulum": "Nuova installazione",
  "Uygulamayı yeni kurduysanız ilk adım bu.":
    "Se hai appena installato l'app, questo è il primo passaggio.",
  "Yeni bir kurulum ya da baştan kontrol için.":
    "Per una nuova installazione o un controllo completo dall'inizio.",
  "Ajanınız kurulumu, Google bağlantısını, PageSpeed anahtarını ve ilk projenizi sırayla kontrol eder, sonra kendini bağlar. Windows paketini de Docker'ı da tanır. Google Cloud'daki adımları siz yaparsınız. Anahtarlar sohbete değil, yalnızca Ayarlar'a girilir.":
    "L'agente controlla a turno l'installazione, la connessione a Google, la chiave PageSpeed ​​e il tuo primo progetto, quindi si connette. Conosce sia il pacchetto Windows che Docker. Esegui tu stesso i passaggi di Google Cloud. Le chiavi vengono inserite solo nelle Impostazioni, mai nella chat.",
