  "Bu bölümde izlenen bir kota yok.":
    "Nessuna quota viene monitorata in questa sezione.",
  "Google ve sistem sınırları": "Google e il sistema limiti",
  "Search Console, GA4 ve PageSpeed'in günlük sınırları, bir de denetim ve rapor üst sınırları. Rakamlar uygulamanın kendi kaydından gelir, Google'a ek istek gitmez. Sınırlar proje başına gösterilir.":
    "I limiti giornalieri di Search Console, GA4 e PageSpeed, oltre ai limiti su controlli e rapporti. Le cifre provengono dai record dell'app, quindi nessuna richiesta aggiuntiva viene inviata a Google. I limiti vengono visualizzati per progetto.",
  "Projeler okunamadı": "Impossibile leggere i progetti",
  "Henüz bir proje yok": "Ancora nessun progetto",
  "Sınırlar proje başına gösterilir. Proje listesi yüklenince burada görünür.":
    "I limiti vengono visualizzati per progetto. Appaiono qui una volta caricato l'elenco dei progetti.",
  "Sınırlar proje başına gösterilir. Bir proje oluşturunca burada görünür.":
    "I limiti vengono visualizzati per progetto. Appaiono qui una volta creato un progetto.",
